		paths.map(async (path) =>
			fs.lstat(join(top, path)).then(
				() => true,
				() => false,
			),
		),
	);
	return paths.filter((_path, i) => !present[i]).map((path) => join(top, path));
}

/** Back to the checkout the run started with: the original HEAD, no changes, the files the restore added gone. */
async function startClean(
	cwd: string,
	original: { head: string; branch: string | undefined },
	added: readonly string[],
): Promise<void> {
	await git(cwd, ["reset", "--quiet", "--hard"]).catch(() => undefined);
	await git(cwd, [
		"checkout",
		"--quiet",
		"--force",
		original.branch ?? original.head,
	]).catch(() => undefined);
	await Promise.all(
		added.map(async (path) => fs.rm(path, { force: true }).catch(() => undefined)),
	);
}

